    return { manifest, metrics: accepted.metrics, sourceChapters: corpus.coverage.sourceChapters,
      extractedChapters: corpus.chapters.length, canonicalPeople: accepted.clusters.length, generatedPairs: 0 };
  } finally { release(); }
}

